UPDATE document_definition_versions
SET schema_json = '{"code":"CANADA_PERMANENT_RESIDENT","country":"CA","documentType":"RESIDENCE_PERMIT","version":"2015","side":"BACK","mrzFormat":"TD1","reading":"Canada permanent resident card back. The mrz value is three lines separated by newlines. Count the characters of each line before you answer: each line must be exactly 30. The third line ends with < fillers. If your count is 29, you dropped one trailing <. Put that < back so the line is 30. The < character belongs only in the mrz field. lastName and firstName are words separated by spaces: a single < between two surnames is a space, and the double << ends the surnames. expirationDate is the six digits immediately after the sex letter on the second line, before the nationality. Ignore the later optional date on that same line.","fields":[{"name":"documentNumber","type":"DOCUMENT_NUMBER","required":true,"hint":"the PD number printed above the machine-readable zone; do not use the front ID No"},{"name":"lastName","type":"NAME","required":false,"normalizer":"ICAO_NAME","hint":"surnames before <<, written with spaces and with no < character. A single < between surnames is a space"},{"name":"firstName","type":"NAME","required":false,"normalizer":"ICAO_NAME","hint":"given names after <<, written with spaces and with no < character"},{"name":"dateOfBirth","type":"DATE","required":false,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"birth date from the MRZ; write yyyy-MM-dd"},{"name":"expirationDate","type":"DATE","required":false,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"the six digits immediately after the sex letter on the second MRZ line, before the nationality. Write yyyy-MM-dd. A year 30 is 2030. Ignore any later date on that line"},{"name":"sex","type":"SEX","required":false,"hint":"sex letter from the MRZ"},{"name":"nationality","type":"NATIONALITY","required":false,"hint":"nationality alpha-3 from the MRZ, such as CMR"},{"name":"mrz","type":"MRZ","required":true,"hint":"three newline-separated lines. Count each line. Each count must be 30. A count of 29 means a trailing < was dropped"},{"name":"placeOfLanding","type":"STRING","required":false,"hint":"labeled Place of landing"},{"name":"residentSince","type":"DATE","required":false,"normalizer":"ISO_DATE","formats":["yyyy-MM-dd"],"hint":"labeled PR Since; write yyyy-MM-dd"},{"name":"eyeColor","type":"STRING","required":false,"hint":"labeled Eyes"},{"name":"heightCm","type":"STRING","required":false,"hint":"labeled Height, digits only"},{"name":"countryOfBirth","type":"NATIONALITY","required":false,"hint":"labeled COB, alpha-3 such as CMR"}],"rules":[]}'
WHERE id = '018f5a00-0000-7000-8000-0000000000e4';
